#include <bits/stdc++.h>
using namespace std;

int brute(const vector<int>& a) {
    int n = (int)a.size();
    int ans = 0;

    for (int l = 0; l < n; ++l) {
        int sum = 0;
        for (int r = l; r < n; ++r) {
            sum += a[r];
            ans = max(ans, sum);
        }
    }

    return ans;
}

int fast(const vector<int>& a) {
    int cur = 0;
    int ans = INT_MIN;

    for (int x : a) {
        cur = max(x, cur + x);
        ans = max(ans, cur);
    }

    return ans;
}

int main() {
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    for (int tc = 1; tc <= 100000; ++tc) {
        int n = rng() % 8 + 1;
        vector<int> a(n);

        for (int i = 0; i < n; ++i) {
            a[i] = (int)(rng() % 21) - 10;
        }

        int x = brute(a);
        int y = fast(a);

        if (x != y) {
            cerr << "Found counterexample!\n";
            for (int v : a) cerr << v << ' ';
            cerr << '\n';
            cerr << "brute = " << x << '\n';
            cerr << "fast = " << y << '\n';
            return 0;
        }
    }

    cerr << "No counterexample found.\n";
    return 0;
}

